#!/usr/bin/env node
/**
 * 生成 ./cordis.patch.yml：一个 - insert: 里只有一行 preset-engineer-lean。
 *
 * 基底是 vendored 的 presets/base/flash-lean-ptc-v3.patch.yml，因此重建不依赖本机
 * DSH 装在哪、也不要求 dsh-flash-presets 处于安装状态。想换安装目录里的上游版本时：
 *   DSH_APP_ROOT=<dsh 安装根> node scripts/build-bundle.mjs
 *
 * 只做可枚举的字符串替换：基底里有 disabled: !!js ... 这类自定义标签，
 * YAML parse/dump 会把它们破坏掉，所以这里绝不解析 YAML。
 *
 *   node scripts/build-bundle.mjs           生成并校验
 *   node scripts/build-bundle.mjs --check   只校验不写
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(dirname(fileURLToPath(import.meta.url)));
const INDENT = " ".repeat(16);
const BASE_NAME = process.env.DS_STACK_BASE || "flash-lean-ptc-v3";
const PERSONA = join(HERE, "presets", "persona-lean.txt");
const BASE_LOCAL = join(HERE, "presets", "base", BASE_NAME + ".patch.yml");
const OUT = join(HERE, "cordis.patch.yml");
const ORDER = Number(process.env.DS_STACK_LEAN_ORDER || 25);
const PKG_NAME = JSON.parse(readFileSync(join(HERE, "package.json"), "utf8")).name;

const readPersona = (path) => readFileSync(path, "utf8").replace(/\r\n/g, "\n").trimEnd();
const indentBlock = (text) => text.split("\n").map((line) => (line ? INDENT + line : "")).join("\n");

/** 只保留 - insert: 起的正文，并丢掉 insert 层（4 空格）的注释。 */
function normalize(raw) {
  const text = raw.replace(/^\uFEFF/, "");
  const at = text.indexOf("- insert:");
  if (at < 0) throw new Error("no '- insert:' in base");
  const [head, ...rest] = text.slice(at).split("\n");
  const kept = rest.filter((line) => !/^ {4}#/.test(line));
  return [head, ...kept].join("\n").trimEnd() + "\n";
}

function applyAll(text, rules) {
  let out = text;
  for (const rule of rules) {
    if (!out.includes(rule.from)) throw new Error(rule.label + ": anchor not found");
    out = out.replace(rule.from, () => rule.to);
  }
  return out;
}

function reverseAll(text, rules) {
  let out = text;
  for (const rule of [...rules].reverse()) {
    if (!out.includes(rule.to)) throw new Error(rule.label + ": round-trip lost the replacement");
    out = out.replace(rule.to, () => rule.from);
  }
  return out;
}

function resolveBase(name) {
  const override = process.env.DSH_APP_ROOT;
  if (override) {
    const rel = join("node_modules", "dsh-flash-presets", "presets", name + ".patch.yml");
    const path = join(override, rel);
    if (!existsSync(path)) throw new Error("DSH_APP_ROOT 里没有 " + rel);
    return { path, origin: "app" };
  }
  if (!existsSync(BASE_LOCAL)) throw new Error("缺 vendored 基底：" + BASE_LOCAL);
  return { path: BASE_LOCAL, origin: "vendored" };
}

const baseInfo = resolveBase(BASE_NAME);
const base = normalize(readFileSync(baseInfo.path, "utf8"));
const persona = readPersona(PERSONA);

const baseId = /^ {4}- id: preset-(\S+)\n/m.exec(base);
const baseConfigId = /^ {8}id: (\S+)\n/m.exec(base);
const orderMatch = /^ {8}order: (\d+)\n/m.exec(base);
const nameLine = /^ {8}name: .*\n/m.exec(base);
const descLine = /^ {8}description: .*\n/m.exec(base);
const suffixMatch = /( {14}suffix: \|-\n)([\s\S]*?)(\n {14}prefix: )/.exec(base);
if (!baseId || !baseConfigId || !orderMatch || !nameLine || !descLine || !suffixMatch) {
  throw new Error("基底结构不符预期（缺 row id / config id / order / name / description / suffix 块）");
}

const skillFrom = "          - id: skill-filesystem\n            name: '@deepseek-ai/dsh-skill-filesystem'\n";
const rules = [
  { label: "row id", from: "    - id: preset-" + baseId[1] + "\n", to: "    - id: preset-engineer-lean\n" },
  {
    label: "config id/name/description",
    from: "        id: " + baseConfigId[1] + "\n" + nameLine[0] + descLine[0],
    to: [
      "        id: engineer-lean",
      "        name: Engineer lean",
      '        description: "精简·PTC v3 的省钱机制（0.25 压缩、8192 剪枝、run_code 折叠）+ 8 个常驻 ds-* 技能与工程纪律，无 guard。"',
    ].join("\n") + "\n",
  },
  { label: "order", from: "        order: " + orderMatch[1] + "\n", to: "        order: " + ORDER + "\n" },
  { label: "persona suffix", from: suffixMatch[1] + suffixMatch[2], to: suffixMatch[1] + indentBlock(persona) },
  {
    label: "skill row",
    // 行里写的模块名必须等于包名，否则加载器解析不到。
    from: skillFrom,
    to: skillFrom + "          - id: skill-engineer\n            name: " + PKG_NAME + "\n",
  },
];

const body = applyAll(base, rules);
if (reverseAll(body, rules) !== base) throw new Error("round-trip check failed");

const GENERATED = "# Generated by scripts/build-bundle.mjs — do not edit by hand.\n"
  + "# base: " + baseInfo.path + " (" + baseInfo.origin + ")\n";
const output = GENERATED + body;

console.log("base: " + baseInfo.origin + " | row preset-engineer-lean | order " + ORDER + " | guard: none");
console.log("persona: " + persona.length + " chars");
console.log("round-trip: ok");
if (process.argv.includes("--check")) { console.log("check: nothing written"); process.exit(0); }
writeFileSync(OUT, output);
console.log("wrote", OUT);
